    J.belly = add([0, 0.345, 0], off);
    J.chest = add([0, 0.440 + br, 0], off);
    J.neckA = add([0, 0.490 + br, 0], off);
    J.neckB = add([0, 0.545 + br, 0], off);
    J.pivot = add([0, 0.530 + br, 0], off);
